from typing import Generator

import pytest
import torch

import flag_gems

from . import base, consts, utils

# cartesian_prod's input is a list of 1-D tensors and its output has
# prod(lengths) rows and K columns, so the cost grows with the product of the
# input lengths. Each case below is one list of 1-D lengths, chosen so the
# output element count (rows * K) stays well under the pointwise ceiling while
# still hitting every kernel branch (A7: keep shapes modest).
CARTESIAN_PROD_CASES = [
    # small: launch-overhead dominated
    [8, 8],
    # K == 2: general chunk kernel, KP == 2
    [4096, 4096],
    # K == 3: general kernel with one padded column tile slot
    [512, 512, 512],
    # K == 4 with even s_last: the row-paired 8-wide store specialisation
    [128, 128, 128, 128],
    # K == 4 with odd s_last: general kernel (the pair path needs even s_last)
    [127, 127, 127, 127],
    # K == 6: more mixed-radix digits per program
    [16, 16, 16, 16, 16, 16],
    # large s_last: more than one program along the row grid axis
    [65536, 4],
]


def _total_rows(lengths):
    rows = 1
    for length in lengths:
        rows *= length
    return rows


class CartesianProdBenchmark(base.Benchmark):
    # The output holds rows * K elements; cap the per-case element count so
    # the combinatorial growth cannot produce an unreasonable allocation.
    MAX_OUTPUT_ELEMENTS = 2**28

    def __init__(self, *args, input_fn, **kwargs):
        super().__init__(*args, **kwargs)
        self.input_fn = input_fn

    def set_shapes(self, shape_file_path=None):
        # The harness ships (M, N) shape pairs; this operator takes a list of
        # 1-D lengths, so the sweep is defined here instead (same pattern as
        # the merged atleast_2d benchmark).
        self.shapes = [
            lengths
            for lengths in CARTESIAN_PROD_CASES
            if _total_rows(lengths) * len(lengths) <= self.MAX_OUTPUT_ELEMENTS
        ]

    def get_input_iter(self, dtype) -> Generator:
        for lengths in self.shapes:
            yield from self.input_fn(lengths, dtype, self.device)


def _input_fn(lengths, dtype, device):
    tensors = [
        utils.generate_tensor_input((length,), dtype, device) for length in lengths
    ]
    # Yield a 1-tuple whose single element is the TensorList argument: the
    # harness unpacks each yielded item as the call argument list, so this
    # produces exactly ``op(tensors_list)`` on both the torch and gems sides.
    # (Yielding ``[tensors],`` instead would pass a nested list and pybind
    # rejects it for the Tensor[] parameter.)
    yield (tensors,)


@pytest.mark.cartesian_prod
def test_cartesian_prod():
    bench = CartesianProdBenchmark(
        op_name="cartesian_prod",
        input_fn=_input_fn,
        torch_op=torch.ops.aten.cartesian_prod,
        gems_op=flag_gems.cartesian_prod,
        dtypes=consts.FLOAT_DTYPES + consts.INT_DTYPES + consts.BOOL_DTYPES,
    )
    bench.run()
